(()=>{document.addEventListener("DOMContentLoaded",()=>{let s=document.querySelectorAll(".ws-payment-icons");s.length&&s.forEach(t=>{t.querySelectorAll(".ws-payment-icons__item").forEach(e=>{e.addEventListener("focus",()=>{e.classList.add("is-focused")}),e.addEventListener("blur",()=>{e.classList.remove("is-focused")})})})});})();
